<?php
/**
 * Product search helpers for the UNIFORMA catalog.
 */

if (! defined('ABSPATH')) {
    exit;
}

if (! function_exists('uniforma_is_product_search_page')) {
    /**
     * Detects product searches generated by the global header form.
     */
    function uniforma_is_product_search_page()
    {
        if (! is_search()) {
            return false;
        }

        $post_type = get_query_var('post_type');

        if (is_array($post_type)) {
            return in_array('product', $post_type, true);
        }

        if ($post_type === 'product') {
            return true;
        }

        if (! isset($_GET['post_type'])) {
            return false;
        }

        $requested_post_type = wp_unslash($_GET['post_type']);

        if (is_array($requested_post_type)) {
            return in_array('product', array_map('sanitize_key', $requested_post_type), true);
        }

        return sanitize_key((string) $requested_post_type) === 'product';
    }
}

if (! function_exists('uniforma_product_search_normalize')) {
    /**
     * Converts user and catalog text into a comparable, accent-free string.
     */
    function uniforma_product_search_normalize($value)
    {
        $value = html_entity_decode(wp_strip_all_tags((string) $value), ENT_QUOTES, 'UTF-8');
        $value = remove_accents($value);
        $value = function_exists('mb_strtolower')
            ? mb_strtolower($value, 'UTF-8')
            : strtolower($value);
        $value = preg_replace('/[^a-z0-9]+/u', ' ', $value);
        $value = preg_replace('/\s+/', ' ', (string) $value);

        return trim((string) $value);
    }
}

if (! function_exists('uniforma_product_search_token_variants')) {
    /**
     * Generates conservative singular/plural variants for common searches.
     */
    function uniforma_product_search_token_variants($token)
    {
        $token = uniforma_product_search_normalize($token);

        if ($token === '') {
            return array();
        }

        $variants = array($token => $token);
        $length = strlen($token);

        if ($length > 3 && substr($token, -1) === 's') {
            $without_s = substr($token, 0, -1);

            if (strlen($without_s) >= 3) {
                $variants[$without_s] = $without_s;
            }
        }

        if ($length > 4 && substr($token, -2) === 'es') {
            $without_es = substr($token, 0, -2);

            if (strlen($without_es) >= 3) {
                $variants[$without_es] = $without_es;
            }
        }

        if ($length > 2 && substr($token, -1) !== 's') {
            $plural_s = $token . 's';
            $plural_es = $token . 'es';
            $variants[$plural_s] = $plural_s;
            $variants[$plural_es] = $plural_es;
        }

        // Common Spanish adjective gender variants: negro/negra,
        // clasico/clasica, medico/medica and their plural forms.
        foreach (array_values($variants) as $variant) {
            $variant_length = strlen($variant);

            if ($variant_length > 3 && substr($variant, -1) === 'a') {
                $gender_variant = substr($variant, 0, -1) . 'o';
                $variants[$gender_variant] = $gender_variant;
            } elseif ($variant_length > 3 && substr($variant, -1) === 'o') {
                $gender_variant = substr($variant, 0, -1) . 'a';
                $variants[$gender_variant] = $gender_variant;
            } elseif ($variant_length > 4 && substr($variant, -2) === 'as') {
                $gender_variant = substr($variant, 0, -2) . 'os';
                $variants[$gender_variant] = $gender_variant;
            } elseif ($variant_length > 4 && substr($variant, -2) === 'os') {
                $gender_variant = substr($variant, 0, -2) . 'as';
                $variants[$gender_variant] = $gender_variant;
            }
        }

        return array_values($variants);
    }
}

if (! function_exists('uniforma_product_search_tokens')) {
    /**
     * Removes connector words so searches such as "remera de mujer" stay useful.
     */
    function uniforma_product_search_tokens($query)
    {
        $normalized_query = uniforma_product_search_normalize($query);

        if ($normalized_query === '') {
            return array();
        }

        $stop_words = array(
            'a', 'al', 'con', 'de', 'del', 'el', 'en', 'la', 'las', 'los',
            'o', 'para', 'por', 'sin', 'un', 'una', 'unas', 'unos', 'y',
        );
        $tokens = array();

        foreach (explode(' ', $normalized_query) as $token) {
            if ($token === '' || in_array($token, $stop_words, true)) {
                continue;
            }

            if (strlen($token) < 2) {
                continue;
            }

            $tokens[$token] = $token;
        }

        if (empty($tokens) && strlen($normalized_query) >= 2) {
            $tokens[$normalized_query] = $normalized_query;
        }

        return array_values($tokens);
    }
}

if (! function_exists('uniforma_product_search_index_cache_key')) {
    function uniforma_product_search_index_cache_key()
    {
        return 'uniforma_product_search_index_v150';
    }
}

if (! function_exists('uniforma_product_search_excluded_ids')) {
    /**
     * Honors WooCommerce search visibility and the hide-out-of-stock setting.
     */
    function uniforma_product_search_excluded_ids()
    {
        if (! function_exists('wc_get_product_visibility_term_ids') || ! taxonomy_exists('product_visibility')) {
            return array();
        }

        $visibility_terms = wc_get_product_visibility_term_ids();
        $term_ids = array();

        if (! empty($visibility_terms['exclude-from-search'])) {
            $term_ids[] = (int) $visibility_terms['exclude-from-search'];
        }

        if (get_option('woocommerce_hide_out_of_stock_items') === 'yes' && ! empty($visibility_terms['outofstock'])) {
            $term_ids[] = (int) $visibility_terms['outofstock'];
        }

        if (empty($term_ids)) {
            return array();
        }

        $object_ids = get_objects_in_term($term_ids, 'product_visibility');

        if (is_wp_error($object_ids)) {
            return array();
        }

        return array_values(array_unique(array_map('intval', (array) $object_ids)));
    }
}

if (! function_exists('uniforma_product_search_build_index')) {
    /**
     * Builds a compact index containing products, categories, rubros, tags,
     * attributes, descriptions and parent/variation SKUs.
     */
    function uniforma_product_search_build_index()
    {
        global $wpdb;

        $products = $wpdb->get_results(
            "SELECT ID, post_title, post_name, post_excerpt, post_content, menu_order
             FROM {$wpdb->posts}
             WHERE post_type = 'product' AND post_status = 'publish'
             ORDER BY menu_order ASC, post_title ASC"
        );

        if (empty($products)) {
            return array();
        }

        $product_ids = array_map('intval', wp_list_pluck($products, 'ID'));
        $id_list = implode(',', $product_ids);
        $sku_map = array();
        $variation_sku_map = array();
        $term_map = array();

        $sku_rows = $wpdb->get_results(
            "SELECT post_id, meta_value
             FROM {$wpdb->postmeta}
             WHERE meta_key = '_sku'
               AND post_id IN ({$id_list})
               AND meta_value <> ''"
        );

        foreach ((array) $sku_rows as $row) {
            $sku_map[(int) $row->post_id] = (string) $row->meta_value;
        }

        $variation_sku_rows = $wpdb->get_results(
            "SELECT variations.post_parent AS product_id,
                    GROUP_CONCAT(DISTINCT sku.meta_value SEPARATOR ' ') AS variation_skus
             FROM {$wpdb->posts} variations
             INNER JOIN {$wpdb->postmeta} sku
                     ON sku.post_id = variations.ID
                    AND sku.meta_key = '_sku'
                    AND sku.meta_value <> ''
             WHERE variations.post_type = 'product_variation'
               AND variations.post_status = 'publish'
               AND variations.post_parent IN ({$id_list})
             GROUP BY variations.post_parent"
        );

        foreach ((array) $variation_sku_rows as $row) {
            $variation_sku_map[(int) $row->product_id] = (string) $row->variation_skus;
        }

        $term_rows = $wpdb->get_results(
            "SELECT relationships.object_id AS product_id,
                    GROUP_CONCAT(
                        DISTINCT CONCAT(COALESCE(terms.name, ''), ' ', COALESCE(terms.slug, ''))
                        SEPARATOR ' '
                    ) AS search_terms
             FROM {$wpdb->term_relationships} relationships
             INNER JOIN {$wpdb->term_taxonomy} taxonomy
                     ON taxonomy.term_taxonomy_id = relationships.term_taxonomy_id
             INNER JOIN {$wpdb->terms} terms
                     ON terms.term_id = taxonomy.term_id
             WHERE relationships.object_id IN ({$id_list})
               AND (
                    taxonomy.taxonomy IN ('product_cat', 'product_tag')
                    OR taxonomy.taxonomy LIKE 'pa_%'
               )
             GROUP BY relationships.object_id"
        );

        foreach ((array) $term_rows as $row) {
            $term_map[(int) $row->product_id] = (string) $row->search_terms;
        }

        $excluded_ids = array_flip(uniforma_product_search_excluded_ids());
        $index = array();

        foreach ($products as $product_row) {
            $product_id = (int) $product_row->ID;

            if (isset($excluded_ids[$product_id])) {
                continue;
            }

            $title = uniforma_product_search_normalize($product_row->post_title);
            $slug = uniforma_product_search_normalize($product_row->post_name);
            $description = uniforma_product_search_normalize(
                $product_row->post_excerpt . ' ' . $product_row->post_content
            );
            $taxonomy = uniforma_product_search_normalize(
                isset($term_map[$product_id]) ? $term_map[$product_id] : ''
            );
            $sku = uniforma_product_search_normalize(
                (isset($sku_map[$product_id]) ? $sku_map[$product_id] : '') . ' ' .
                (isset($variation_sku_map[$product_id]) ? $variation_sku_map[$product_id] : '')
            );

            $index[] = array(
                'id' => $product_id,
                'title' => $title,
                'title_raw' => (string) $product_row->post_title,
                'slug' => $slug,
                'taxonomy' => $taxonomy,
                'description' => $description,
                'sku' => $sku,
                'combined' => trim($title . ' ' . $slug . ' ' . $taxonomy . ' ' . $sku . ' ' . $description),
                'menu_order' => (int) $product_row->menu_order,
            );
        }

        return $index;
    }
}

if (! function_exists('uniforma_product_search_get_index')) {
    function uniforma_product_search_get_index()
    {
        $cache_key = uniforma_product_search_index_cache_key();
        $index = get_transient($cache_key);

        if (is_array($index)) {
            return $index;
        }

        $index = uniforma_product_search_build_index();
        set_transient($cache_key, $index, 6 * HOUR_IN_SECONDS);

        return $index;
    }
}

if (! function_exists('uniforma_product_search_field_has_variants')) {
    function uniforma_product_search_field_has_variants($field, $variants)
    {
        if ($field === '') {
            return false;
        }

        foreach ((array) $variants as $variant) {
            if ($variant !== '' && strpos($field, $variant) !== false) {
                return true;
            }
        }

        return false;
    }
}

if (! function_exists('uniforma_product_search_score_entry')) {
    /**
     * Scores one product and reports how many meaningful tokens matched.
     */
    function uniforma_product_search_score_entry($entry, $normalized_query, $token_groups)
    {
        $score = 500;

        if ($entry['sku'] === $normalized_query && $normalized_query !== '') {
            $score = 0;
        } elseif ($entry['title'] === $normalized_query) {
            $score = 4;
        } elseif ($normalized_query !== '' && strpos($entry['title'], $normalized_query) === 0) {
            $score = 15;
        } elseif ($normalized_query !== '' && strpos($entry['title'], $normalized_query) !== false) {
            $score = 28;
        } elseif ($normalized_query !== '' && strpos($entry['sku'], $normalized_query) !== false) {
            $score = 36;
        } elseif ($normalized_query !== '' && strpos($entry['taxonomy'], $normalized_query) !== false) {
            $score = 48;
        } elseif ($normalized_query !== '' && strpos($entry['description'], $normalized_query) !== false) {
            $score = 76;
        }

        $matched_tokens = 0;

        foreach ($token_groups as $variants) {
            if (uniforma_product_search_field_has_variants($entry['title'], $variants)) {
                $matched_tokens++;
                $score -= 18;
            } elseif (uniforma_product_search_field_has_variants($entry['sku'], $variants)) {
                $matched_tokens++;
                $score -= 15;
            } elseif (uniforma_product_search_field_has_variants($entry['taxonomy'], $variants)) {
                $matched_tokens++;
                $score -= 11;
            } elseif (uniforma_product_search_field_has_variants($entry['description'], $variants)) {
                $matched_tokens++;
                $score -= 4;
            }
        }

        return array(
            'score' => $score,
            'matched_tokens' => $matched_tokens,
        );
    }
}

if (! function_exists('uniforma_product_search_find')) {
    /**
     * Returns product IDs ordered by relevance.
     *
     * When a multi-word query has no full match, it falls back to products that
     * match at least half of the meaningful words.
     */
    function uniforma_product_search_find($query, $limit = 0)
    {
        $normalized_query = uniforma_product_search_normalize($query);
        $tokens = uniforma_product_search_tokens($query);

        if ($normalized_query === '' || strlen($normalized_query) < 2 || empty($tokens)) {
            return array(
                'ids' => array(),
                'fallback' => false,
                'normalized_query' => $normalized_query,
            );
        }

        $token_groups = array();

        foreach ($tokens as $token) {
            $token_groups[] = uniforma_product_search_token_variants($token);
        }

        $required_tokens = count($token_groups);
        $minimum_partial_tokens = max(1, (int) ceil($required_tokens / 2));
        $full_matches = array();
        $partial_matches = array();

        foreach (uniforma_product_search_get_index() as $entry) {
            $match = uniforma_product_search_score_entry($entry, $normalized_query, $token_groups);

            if ($match['matched_tokens'] === $required_tokens) {
                $entry['score'] = $match['score'];
                $entry['matched_tokens'] = $match['matched_tokens'];
                $full_matches[] = $entry;
            } elseif ($required_tokens > 1 && $match['matched_tokens'] >= $minimum_partial_tokens) {
                $entry['score'] = $match['score'] + (($required_tokens - $match['matched_tokens']) * 100);
                $entry['matched_tokens'] = $match['matched_tokens'];
                $partial_matches[] = $entry;
            }
        }

        $matches = ! empty($full_matches) ? $full_matches : $partial_matches;
        $used_fallback = empty($full_matches) && ! empty($partial_matches);

        usort($matches, static function ($left, $right) {
            if ($left['matched_tokens'] !== $right['matched_tokens']) {
                return $right['matched_tokens'] <=> $left['matched_tokens'];
            }

            if ($left['score'] !== $right['score']) {
                return $left['score'] <=> $right['score'];
            }

            if ($left['menu_order'] !== $right['menu_order']) {
                return $left['menu_order'] <=> $right['menu_order'];
            }

            return strnatcasecmp($left['title_raw'], $right['title_raw']);
        });

        $ids = array_map('intval', wp_list_pluck($matches, 'id'));

        if ((int) $limit > 0) {
            $ids = array_slice($ids, 0, (int) $limit);
        }

        return array(
            'ids' => $ids,
            'fallback' => $used_fallback,
            'normalized_query' => $normalized_query,
        );
    }
}

if (! function_exists('uniforma_product_search_flush_index')) {
    function uniforma_product_search_flush_index()
    {
        delete_transient(uniforma_product_search_index_cache_key());
    }
}

if (! function_exists('uniforma_product_search_maybe_flush_for_post')) {
    function uniforma_product_search_maybe_flush_for_post($post_id)
    {
        $post_type = get_post_type((int) $post_id);

        if (in_array($post_type, array('product', 'product_variation'), true)) {
            uniforma_product_search_flush_index();
        }
    }
}

if (! function_exists('uniforma_product_search_maybe_flush_for_terms')) {
    function uniforma_product_search_maybe_flush_for_terms($object_id, $terms, $tt_ids, $taxonomy)
    {
        if (
            $taxonomy === 'product_cat' ||
            $taxonomy === 'product_tag' ||
            strpos((string) $taxonomy, 'pa_') === 0
        ) {
            uniforma_product_search_flush_index();
        }
    }
}

if (! function_exists('uniforma_product_search_maybe_flush_for_term_edit')) {
    function uniforma_product_search_maybe_flush_for_term_edit($term_id, $tt_id = 0, $taxonomy = '')
    {
        if (
            $taxonomy === 'product_cat' ||
            $taxonomy === 'product_tag' ||
            strpos((string) $taxonomy, 'pa_') === 0
        ) {
            uniforma_product_search_flush_index();
        }
    }
}

add_action('save_post_product', 'uniforma_product_search_flush_index');
add_action('save_post_product_variation', 'uniforma_product_search_flush_index');
add_action('before_delete_post', 'uniforma_product_search_maybe_flush_for_post');
add_action('set_object_terms', 'uniforma_product_search_maybe_flush_for_terms', 10, 4);
add_action('created_term', 'uniforma_product_search_maybe_flush_for_term_edit', 10, 3);
add_action('edited_term', 'uniforma_product_search_maybe_flush_for_term_edit', 10, 3);
add_action('delete_term', 'uniforma_product_search_maybe_flush_for_term_edit', 10, 3);
